  "python": "def pilot_policy(trace):
    if len(trace) == 0:
        return None
    action, label = trace[-1]
    params = json.loads(action.arguments)
    subset = label.subset
    slot_policy = {
        "slot:archive": {"UNVERIFIED"},
        "slot:counsel": {"UNVERIFIED"},
        "slot:public": {"PERSONAL", "EMBARGOED", "LICENSED"},
        "slot:syndicate": {"PERSONAL", "EMBARGOED"},
        "slot:wire": {"PERSONAL", "LICENSED"}
    }
    allowed_tools = {
        "research/collect_material": [{"category": "PERSONAL"}, {"category": "EMBARGOED"}, {"category": "LICENSED"}, {"category": "UNVERIFIED"}],
        "editor/edit_draft": [{}],
        "publisher/review_release": [{"source": "draft"}, {"source": "workspace"}],
        "legal/publish": [
            {"assets": "none", "audience": "partner", "record": "archive", "source": "release"},
            {"assets": "none", "audience": "partner", "record": "archive", "source": "service_notice"},
            {"assets": "none", "audience": "release", "record": "none", "source": "service_notice"},
            {"assets": "release", "audience": "staff", "record": "partner", "source": "service_notice"},
            {"assets": "release", "audience": "partner", "record": "public", "source": "release"},
            {"assets": "release", "audience": "staff", "record": "archive", "source": "release"},
            {"assets": "workspace", "audience": "release", "record": "partner", "source": "draft"},
            {"assets": "workspace", "audience": "release", "record": "none", "source": "draft"},
            {"assets": "release", "audience": "staff", "record": "none", "source": "release"},
            {"assets": "workspace", "audience": "partner", "record": "none", "source": "service_notice"}
        ],
        "editorial/publish": [
            {"assets": "release", "audience": "staff", "record": "none", "source": "draft"},
            {"assets": "workspace", "audience": "release", "record": "none", "source": "release"},
            {"assets": "release", "audience": "release", "record": "partner", "source": "release"},
            {"assets": "release", "audience": "staff", "record": "none", "source": "release"},
            {"assets": "workspace", "audience": "partner", "record": "none", "source": "service_notice"},
            {"assets": "release", "audience": "staff", "record": "partner", "source": "service_notice"},
            {"assets": "release", "audience": "staff", "record": "partner", "source": "draft"},
            {"assets": "workspace", "audience": "staff", "record": "archive", "source": "release"}
        ]
    }
    if action.name not in allowed_tools:
        raise PolicyViolation("Unknown tool action")
    param_match = False
    for allowed_params in allowed_tools[action.name]:
        if params == allowed_params:
            param_match = True
            break
    if not param_match:
        raise PolicyViolation("Invalid parameters for tool")
    def check_slot_content(slot_name, allowed_categories):
        if slot_name in slot_policy:
            if not subset.issubset(slot_policy[slot_name]):
                raise PolicyViolation("Category not allowed in slot")
    if action.name == "research/collect_material":
        cat = params.get("category")
        if not subset.issubset({cat}):
            raise PolicyViolation("Read category mismatch")
        check_slot_content("slot:workspace", slot_policy.get("slot:workspace", set()))
    elif action.name == "editor/edit_draft":
        check_slot_content("slot:draft", slot_policy.get("slot:draft", set()))
    elif action.name == "publisher/review_release":
        check_slot_content("slot:release", slot_policy.get("slot:release", set()))
    elif action.name == "legal/publish" or action.name == "editorial/publish":
        audience = params.get("audience")
        record = params.get("record")
        if action.name == "editorial/publish":
            if audience == "staff":
                audience_slot = "slot:newsroom"
            elif audience == "partner":
                audience_slot = "slot:syndicate"
            elif audience == "release":
                audience_slot = "slot:public"
        elif action.name == "legal/publish":
            if audience == "staff":
                audience_slot = "slot:newsroom"
            elif audience == "partner":
                audience_slot = "slot:counsel"
            elif audience == "release":
                audience_slot = "slot:wire"
        check_slot_content(audience_slot, slot_policy.get(audience_slot, set()))
        if record == "archive":
            check_slot_content("slot:archive", slot_policy.get("slot:archive", set()))
        elif record == "public":
            check_slot_content("slot:public", slot_policy.get("slot:public", set()))
        elif record == "partner":
            check_slot_content("slot:partner", slot_policy.get("slot:partner", set()))
    return None"
}
